package detective;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.*;

public class Main extends JFrame {
    static final Color BG=new Color(18,20,24), PANEL=new Color(28,31,37), PANEL2=new Color(35,39,46);
    static final Color TEXT=new Color(235,238,242), MUTED=new Color(160,166,176), ACCENT=new Color(205,155,82);
    final Game game=new Game(); final CardLayout cards=new CardLayout(); final JPanel screens=new JPanel(cards);
    final JTextArea journal=new JTextArea(); final JPanel suspectsPanel=new JPanel(), locationsPanel=new JPanel(), evidencePanel=new JPanel(), deductionPanel=new JPanel();
    Main(){
        setTitle("CASEFILE: 47 — The Last Night at MIT University"); setSize(1180,760); setMinimumSize(new Dimension(980,650));
        setLocationRelativeTo(null); setDefaultCloseOperation(EXIT_ON_CLOSE);
        screens.add(startScreen(),"START"); screens.add(caseScreen(),"CASE"); screens.add(suspectsScreen(),"SUSPECTS");
        screens.add(locationsScreen(),"LOCATIONS"); screens.add(evidenceScreen(),"EVIDENCE"); screens.add(deductionScreen(),"DEDUCTION");
        screens.add(accusationScreen(),"ACCUSATION"); screens.add(endingScreen(),"ENDING"); add(screens); show("START");
    }
    JPanel base(){JPanel p=new JPanel(new BorderLayout(18,18));p.setBackground(BG);p.setBorder(new EmptyBorder(25,30,25,30));return p;}
    JPanel panel(){JPanel p=new JPanel();p.setBackground(PANEL);p.setBorder(new EmptyBorder(18,18,18,18));return p;}
    JLabel label(String s,int n,Color c){JLabel l=new JLabel(s);l.setFont(new Font("SansSerif",Font.PLAIN,n));l.setForeground(c);return l;}
    JTextArea area(String s,int w,int h){JTextArea a=new JTextArea(s);a.setEditable(false);a.setLineWrap(true);a.setWrapStyleWord(true);a.setFont(new Font("SansSerif",Font.PLAIN,14));a.setForeground(TEXT);a.setBackground(PANEL2);a.setBorder(new EmptyBorder(15,15,15,15));a.setPreferredSize(new Dimension(w,h));return a;}
    JButton button(String s){JButton b=new JButton(s);b.setFocusPainted(false);b.setForeground(TEXT);b.setBackground(PANEL2);b.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(65,70,78)),new EmptyBorder(10,16,10,16)));return b;}
    JButton nav(String s,String screen){JButton b=button(s);b.addActionListener(e->show(screen));return b;}
    JPanel header(String a,String b){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);p.add(label(a,12,ACCENT),BorderLayout.NORTH);p.add(label(b,25,TEXT),BorderLayout.CENTER);return p;}
    void show(String s){cards.show(screens,s);refresh();}
    void refresh(){journal.setText(game.journalText());refreshSuspects();refreshLocations();refreshEvidence();refreshDeduction();}

    JPanel startScreen(){
        JPanel p=base(), c=new JPanel();c.setOpaque(false);c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));
        JLabel top=label("MET INSTITUTE OF TECHNOLOGY",13,ACCENT);top.setAlignmentX(.5f);
        JLabel t=label("CASEFILE: 47",58,TEXT);t.setFont(new Font("Serif",Font.BOLD,58));t.setAlignmentX(.5f);
        JLabel sub=label("THE LAST NIGHT AT MIT UNIVERSITY",18,MUTED);sub.setAlignmentX(.5f);
        JTextArea intro=area("11:47 PM.\n\nA brilliant engineering student is found dead in the basement parking area of a university that should have been asleep.\n\nFive people had reasons to hate him. One of them knows more than they are saying.\n\nYour job is not to guess the murderer. Your job is to prove what happened.",560,180);intro.setAlignmentX(.5f);
        JButton b=button("START INVESTIGATION");b.setAlignmentX(.5f);b.addActionListener(e->{game.reset();show("CASE");});
        c.add(Box.createVerticalGlue());c.add(top);c.add(Box.createVerticalStrut(8));c.add(t);c.add(sub);c.add(Box.createVerticalStrut(28));c.add(intro);c.add(Box.createVerticalStrut(25));c.add(b);c.add(Box.createVerticalGlue());p.add(c);return p;
    }
    JPanel caseScreen(){
        JPanel p=base();p.add(header("CASE FILE","The Last Night at MIT University"),BorderLayout.NORTH);JPanel body=new JPanel(new BorderLayout(15,15));body.setOpaque(false);
        JPanel left=panel();left.setLayout(new BoxLayout(left,BoxLayout.Y_AXIS));left.add(label("VICTIM",12,ACCENT));left.add(label("Nitheesh Reedy",24,TEXT));left.add(label("Final-year engineering student",13,MUTED));left.add(Box.createVerticalStrut(20));left.add(label("INITIAL REPORT",12,ACCENT));
        left.add(area("Nitheesh was found unconscious in the basement parking area at approximately 11:47 PM.\n\nA student discovered him beside a parked car. His phone was missing. There was blood on the floor, but the scene does not immediately explain the cause of death.\n\nEarlier that evening, Nitheesh had told someone that he had finally found proof of something he had been investigating for weeks.",360,270));
        JButton b=button("OPEN INVESTIGATION");b.addActionListener(e->show("LOCATIONS"));left.add(Box.createVerticalStrut(15));left.add(b);body.add(left,BorderLayout.WEST);
        JPanel right=panel();right.setLayout(new BorderLayout(10,10));right.add(label("DETECTIVE'S JOURNAL",14,ACCENT),BorderLayout.NORTH);journal.setEditable(false);journal.setFont(new Font("SansSerif",Font.PLAIN,14));journal.setForeground(TEXT);journal.setBackground(PANEL2);journal.setLineWrap(true);journal.setBorder(new EmptyBorder(15,15,15,15));right.add(new JScrollPane(journal),BorderLayout.CENTER);
        JPanel nav=new JPanel(new FlowLayout(FlowLayout.LEFT));nav.setOpaque(false);for(String[] x:new String[][]{{"Suspects","SUSPECTS"},{"Locations","LOCATIONS"},{"Evidence","EVIDENCE"},{"Deduction Board","DEDUCTION"},{"Accuse","ACCUSATION"}})nav.add(nav(x[0],x[1]));right.add(nav,BorderLayout.SOUTH);body.add(right,BorderLayout.CENTER);p.add(body);return p;
    }
    JPanel suspectsScreen(){JPanel p=base();p.add(header("PEOPLE OF INTEREST","Five suspects. Five different motives."),BorderLayout.NORTH);suspectsPanel.setLayout(new GridLayout(1,5,10,10));suspectsPanel.setOpaque(false);p.add(suspectsPanel);p.add(nav("Back to Case","CASE"),BorderLayout.SOUTH);return p;}
    void refreshSuspects(){if(suspectsPanel==null)return;suspectsPanel.removeAll();for(Suspect s:game.suspects.values()){JPanel c=panel();c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));JLabel portrait=label(s.initials,38,ACCENT);portrait.setFont(new Font("Serif",Font.BOLD,38));portrait.setAlignmentX(.5f);c.add(Box.createVerticalStrut(8));c.add(portrait);JLabel n=label(s.name,16,TEXT);n.setAlignmentX(.5f);c.add(n);JLabel r=label(s.role,12,MUTED);r.setAlignmentX(.5f);c.add(r);c.add(Box.createVerticalStrut(10));JLabel m=label("Motive: "+s.motive,11,TEXT);m.setAlignmentX(.5f);c.add(m);JButton b=button(s.interviewed?"RE-INTERVIEW":"INTERVIEW");b.setAlignmentX(.5f);b.addActionListener(e->interview(s));c.add(Box.createVerticalStrut(12));c.add(b);suspectsPanel.add(c);}suspectsPanel.revalidate();suspectsPanel.repaint();}
    void interview(Suspect s){StringBuilder x=new StringBuilder(s.name+"\n\n");for(String d:s.dialogue)x.append(d).append("\n");int r=JOptionPane.showOptionDialog(this,new JScrollPane(area(x.toString(),650,330)),"Interview — "+s.name,JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,new String[]{"Continue questioning","Close"},"Continue questioning");if(r==0)followUp(s);s.interviewed=true;game.journal("Interviewed "+s.name+".");refresh();}
    void followUp(Suspect s){String q,a;switch(s.name){case "Manjunath S"-> {q="Nitheesh told you about his research. Why did you argue with him?";a="I wanted him to stop. He was digging into something dangerous. I thought he was putting both of us at risk.";}case "Om Prakesh"->{q="You threatened Nitheesh. Where were you at 11:20 PM?";a="I was near the old academic block. Yes, I hated him. But I did not kill him.";}case "Aaradhya Rao"->{q="You knew about the secret. Why did you hide that?";a="He asked me not to tell anyone. We had argued because I wanted him to go to the authorities.";}case "Maniappa"->{q="What exactly was your personal conflict with Nitheesh?";a="Nitheesh accused me of hiding a hostel access problem. He said he would report me.";}default->{q="You knew Nitheesh's computer password. Did you access it?";a="I knew the password because we lived together. I looked at his computer earlier, but I did not delete anything.";}}JOptionPane.showMessageDialog(this,"<html><b>Detective:</b> "+q+"<br><br><b>"+s.name+":</b> "+a+"</html>","Follow-up",JOptionPane.INFORMATION_MESSAGE);if(s.name.equals("Yashwanth"))game.addEvidence("Password access");if(s.name.equals("Aaradhya Rao"))game.addEvidence("Aaradhya knew about the research");if(s.name.equals("Maniappa"))game.addEvidence("Maniappa had a personal conflict");game.journal("Follow-up information obtained from "+s.name+".");}
    JPanel locationsScreen(){JPanel p=base();p.add(header("CAMPUS MAP","Explore the places connected to Nitheesh's final night."),BorderLayout.NORTH);locationsPanel.setLayout(new GridLayout(3,3,12,12));locationsPanel.setOpaque(false);p.add(locationsPanel);p.add(nav("Back to Case","CASE"),BorderLayout.SOUTH);return p;}
    void refreshLocations(){locationsPanel.removeAll();for(Location l:game.locations){JButton b=button(l.name);b.setToolTipText(l.description);b.addActionListener(e->explore(l));locationsPanel.add(b);}locationsPanel.revalidate();locationsPanel.repaint();}
    void explore(Location l){String r=l.inspect(game);JOptionPane.showMessageDialog(this,"<html><b>"+l.name+"</b><br><br>"+r.replace("\n","<br>")+"</html>","Location",JOptionPane.INFORMATION_MESSAGE);game.journal("Explored "+l.name+".");refresh();}
    JPanel evidenceScreen(){JPanel p=base();p.add(header("EVIDENCE LOCKER","Every clue matters. Not every clue means what it first appears to mean."),BorderLayout.NORTH);evidencePanel.setLayout(new BoxLayout(evidencePanel,BoxLayout.Y_AXIS));evidencePanel.setOpaque(false);p.add(new JScrollPane(evidencePanel));p.add(nav("Back to Case","CASE"),BorderLayout.SOUTH);return p;}
    void refreshEvidence(){evidencePanel.removeAll();if(game.evidence.isEmpty())evidencePanel.add(label("No evidence collected yet.",15,MUTED));else for(String e:game.evidence){JPanel r=panel();r.setLayout(new BorderLayout());r.add(label(e,15,TEXT));evidencePanel.add(r);evidencePanel.add(Box.createVerticalStrut(6));}evidencePanel.revalidate();evidencePanel.repaint();}
    JPanel deductionScreen(){JPanel p=base();p.add(header("DEDUCTION BOARD","Connect clues. Build a theory. Do not confuse suspicion with proof."),BorderLayout.NORTH);deductionPanel.setLayout(new BoxLayout(deductionPanel,BoxLayout.Y_AXIS));deductionPanel.setOpaque(false);p.add(new JScrollPane(deductionPanel),BorderLayout.CENTER);JPanel c=new JPanel(new FlowLayout(FlowLayout.LEFT));c.setOpaque(false);
        addConnectionButton(c,"Connect Research → Password",()->{if(game.hasEvidence("Deleted research file")&&game.hasEvidence("Password access")){game.connections.add("Deleted research file → Password access");game.journal("Deduction: someone with password access could have reached Nitheesh's research.");popup("Connection made","The deleted research file and password access now form a credible lead.");}else popup("Missing clues","You need the deleted research file and password access first.");});
        addConnectionButton(c,"Connect Threat → Om",()->{if(game.hasEvidence("Threatening message")){game.connections.add("Threatening message → Om's motive");game.journal("Deduction: Om had a genuine revenge motive.");popup("Connection made","Om clearly had motive. Motive alone does not establish the murder.");}else popup("Missing clue","Find Om's threatening message first.");});
        addConnectionButton(c,"Connect CCTV → Basement",()->{if(game.hasEvidence("Partial CCTV timestamp")){game.connections.add("CCTV timestamp → Basement movement");game.journal("Deduction: the basement timeline can be reconstructed.");popup("Connection made","The CCTV gap is now part of the timeline.");}else popup("Missing clue","Search the security office.");});
        addConnectionButton(c,"Connect Access Log → Maniappa",()->{if(game.hasEvidence("Hostel access anomaly")){game.connections.add("Hostel access anomaly → Maniappa");game.journal("Deduction: Maniappa could explain the access anomaly.");popup("Connection made","Maniappa is relevant to the access record, but relevance is not guilt.");}else popup("Missing clue","Investigate the hostel office.");});p.add(c,BorderLayout.SOUTH);return p;}
    void addConnectionButton(JPanel p,String s,Runnable r){JButton b=button(s);b.addActionListener(e->{r.run();refresh();});p.add(b);}
    void refreshDeduction(){deductionPanel.removeAll();deductionPanel.add(label("COLLECTED CONNECTIONS",13,ACCENT));deductionPanel.add(Box.createVerticalStrut(8));if(game.connections.isEmpty())deductionPanel.add(label("No connections established yet.",14,MUTED));else for(String c:game.connections){JPanel r=panel();r.add(label("• "+c,15,TEXT));deductionPanel.add(r);deductionPanel.add(Box.createVerticalStrut(6));}deductionPanel.add(Box.createVerticalStrut(20));deductionPanel.add(label("CURRENT THEORY",13,ACCENT));deductionPanel.add(label(game.theory(),14,TEXT));deductionPanel.revalidate();deductionPanel.repaint();}
    JPanel accusationScreen(){JPanel p=base();p.add(header("FINAL ACCUSATION","Name the person responsible and justify your decision."),BorderLayout.NORTH);JPanel c=new JPanel();c.setOpaque(false);c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));JLabel q=label("Who do you accuse of murdering Nitheesh Reedy?",20,TEXT);q.setAlignmentX(.5f);c.add(q);c.add(Box.createVerticalStrut(20));JComboBox<String> box=new JComboBox<>(game.suspectNames());box.setMaximumSize(new Dimension(420,40));box.setAlignmentX(.5f);c.add(box);c.add(Box.createVerticalStrut(20));JTextArea exp=area("Write the key facts you believe prove the accusation.",600,170);exp.setAlignmentX(.5f);c.add(exp);c.add(Box.createVerticalStrut(18));JButton b=button("MAKE ACCUSATION");b.setAlignmentX(.5f);b.addActionListener(e->{game.accusation=(String)box.getSelectedItem();game.explanation=exp.getText();finish();});c.add(b);c.add(Box.createVerticalStrut(15));c.add(label("You are allowed to make mistakes. A wrong accusation is part of the case.",12,MUTED));p.add(c);return p;}
    void finish(){boolean full=game.hasEvidence("Final encrypted file")&&game.hasEvidence("Phone recovered")&&game.connections.size()>=3;boolean strong=game.hasEvidence("Partial CCTV timestamp")&&game.hasEvidence("Deleted research file")&&game.connections.size()>=2;String title,details;if(game.accusation.equals("Manjunath S")){if(full){title="TRUE ENDING — THE COVER-UP EXPOSED";details="You identified Manjunath S.\n\nNitheesh discovered a financial arrangement in which research work was being used to justify money moving through a university-linked project channel. His software was the proof. Manjunath knew about it and tried to stop him.\n\nThe final evidence shows Manjunath arranged the basement meeting, used the argument as cover, and attempted to destroy the research trail. Om's threats, Aaradhya's secrecy and Maniappa's access conflict were real, but none proved the murder.\n\nYour deduction board separated motive from proof. The case is solved.";}else if(strong){title="GOOD ACCUSATION — INCOMPLETE PROOF";details="Your accusation of Manjunath is consistent with the strongest evidence, but you did not recover enough of Nitheesh's final digital evidence to prove the entire chain beyond doubt.";}else{title="CORRECT SUSPECT — WEAK CASE";details="You named the correct suspect, but your evidence is too thin. Several other suspects had genuine motives, and you did not establish the complete timeline.";}}else if(game.accusation.equals("Om Prakesh")){title="WRONG ENDING — THE REVENGE TRAP";details="Om had the strongest obvious motive. His threats were real. But you stopped at motive instead of proving opportunity and method. Om is guilty of threatening Nitheesh, not the murder.";}else if(game.accusation.equals("Aaradhya Rao")){title="WRONG ENDING — THE SECRET WAS NOT MURDER";details="Aaradhya hid Nitheesh's secret because he asked her to protect the research until he could safely expose it. Their argument was genuine, but it did not make her the killer.";}else if(game.accusation.equals("Maniappa")){title="WRONG ENDING — ACCESS IS NOT GUILT";details="Maniappa had a personal conflict with Nitheesh and access to hostel information. That made him relevant, but the access anomaly concerned a separate problem.";}else{title="INCOMPLETE CASE — THE QUIET ROOMMATE";details="Yashwanth knew Nitheesh's password and accessed his computer earlier that day. That is suspicious, but the evidence does not establish that he was the murderer.";}JPanel p=(JPanel)screens.getComponent(7);((JLabel)p.getClientProperty("result")).setText(title);((JTextArea)p.getClientProperty("details")).setText(details);show("ENDING");}
    JPanel endingScreen(){JPanel p=base();p.add(header("CASE CONCLUSION","Casefile 47"),BorderLayout.NORTH);JPanel c=new JPanel();c.setOpaque(false);c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));JLabel r=label("",30,ACCENT);r.setAlignmentX(.5f);JTextArea d=area("",720,330);d.setAlignmentX(.5f);JButton b=button("PLAY CASE AGAIN");b.setAlignmentX(.5f);b.addActionListener(e->{game.reset();show("CASE");});c.add(Box.createVerticalGlue());c.add(r);c.add(Box.createVerticalStrut(20));c.add(d);c.add(Box.createVerticalStrut(20));c.add(b);c.add(Box.createVerticalGlue());p.putClientProperty("result",r);p.putClientProperty("details",d);p.add(c);return p;}
    void popup(String t,String s){JOptionPane.showMessageDialog(this,s,t,JOptionPane.INFORMATION_MESSAGE);}

    static class Suspect{String name,role,initials,motive;boolean interviewed;java.util.List<String> dialogue=new ArrayList<>();Suspect(String n,String r,String i,String m){name=n;role=r;initials=i;motive=m;}}
    static class Location{String name,description;boolean searched;Location(String n,String d){name=n;description=d;}String inspect(Game g){if(searched)return "You search the area again. Nothing new stands out.";searched=true;switch(name){case "Basement Parking"-> {g.addEvidence("Blood pattern at parking bay");g.addEvidence("Partial CCTV timestamp");return "The parking bay shows a small blood pattern rather than a chaotic struggle. A camera covers the entrance, but the recording has a suspicious gap. One detail suggests Nitheesh may have arrived willingly.";}case "Security Office"->{g.addEvidence("Partial CCTV timestamp");g.addEvidence("Security log discrepancy");return "The security log shows a camera interruption between 11:18 and 11:31 PM. The guard insists he did not switch it off. Someone knew exactly when the blind spot would exist.";}case "Hostel Room"->{g.addEvidence("Password access");g.addEvidence("Deleted research file");return "Nitheesh's laptop is still in the room. Several research files are missing, but one deleted-file entry remains. The laptop was accessed using a password known to his roommate.";}case "Hostel Office"->{g.addEvidence("Hostel access anomaly");return "A hostel access record shows an unusual late-night entry connected to a maintenance override. The record points toward the warden's administrative credentials.";}case "Computer Lab"->{g.addEvidence("Research project metadata");return "A backup workstation contains project metadata from Nitheesh's research. The project was not merely academic: it could trace irregular transactions through a university-linked process.";}case "Library"->{g.addEvidence("Nitheesh's notebook");return "A notebook contains three words: money, project, proof. There is also a note telling someone to meet at the basement parking area.";}case "Canteen"->{g.addEvidence("Threatening message");return "You recover a screenshot from a student's phone showing a message from Om: 'Stay away from me or you will regret it.' The timestamp is earlier than the murder.";}case "Engineering Block"->{g.addEvidence("Research project metadata");return "Nitheesh's project presentation file has been edited recently. The edit history contains a user session that should not have been active that night.";}case "Student Club Room"->{g.addEvidence("Aaradhya knew about the research");return "Aaradhya's club notebook contains a reference to Nitheesh's research. She clearly knew about the project, but the note says: Don't let him do this alone.";}default-> {return "Nothing useful found.";}}}}
    static class Game{LinkedHashMap<String,Suspect> suspects=new LinkedHashMap<>();java.util.List<Location> locations=new ArrayList<>();LinkedHashSet<String> evidence=new LinkedHashSet<>(),connections=new LinkedHashSet<>();java.util.List<String> journal=new ArrayList<>();String accusation="",explanation="";Game(){reset();}void reset(){suspects.clear();locations.clear();evidence.clear();connections.clear();journal.clear();accusation="";Suspect a=new Suspect("Manjunath S","Close friend","MS","Nitheesh was about to expose something Manjunath knew about.");a.dialogue.add("I was his closest friend. We argued because he wouldn't stop investigating.");a.dialogue.add("He told me he had proof. I thought he was making a terrible mistake.");a.dialogue.add("I left him alone after our argument.");Suspect b=new Suspect("Om Prakesh","Bullying / revenge motive","OP","Nitheesh repeatedly humiliated him and cost him an opportunity.");b.dialogue.add("Yes, I hated him. Everyone knew that.");b.dialogue.add("I sent him angry messages. I regret that.");b.dialogue.add("But anger doesn't mean I killed him.");Suspect c=new Suspect("Aaradhya Rao","Girlfriend","AR","Their relationship was collapsing, and she knew his secret.");c.dialogue.add("We had an argument. He wanted to go through with something I thought was dangerous.");c.dialogue.add("He asked me to keep quiet about his research.");c.dialogue.add("I didn't understand how serious it was until later.");Suspect d=new Suspect("Maniappa","Hostel warden","MA","Nitheesh accused him of hiding a hostel access problem.");d.dialogue.add("Nitheesh was accusing me of things he didn't understand.");d.dialogue.add("I had administrative access, yes. That doesn't make me a murderer.");d.dialogue.add("We had a personal conflict, but I wanted it settled quietly.");Suspect e=new Suspect("Yashwanth","Roommate","YA","He knew Nitheesh's passwords and had access to his computer.");e.dialogue.add("I knew his password because we were roommates.");e.dialogue.add("I used his computer earlier that day. I shouldn't have.");e.dialogue.add("I didn't know what he was investigating.");for(Suspect s:new Suspect[]{a,b,c,d,e})suspects.put(s.name,s);String[][] ls={{"Basement Parking","Primary crime scene"},{"Security Office","CCTV and night log"},{"Hostel Room","Victim's room and laptop"},{"Hostel Office","Access records"},{"Computer Lab","Research backup"},{"Library","Victim's notes"},{"Canteen","Student conversations"},{"Engineering Block","Project records"},{"Student Club Room","Aaradhya's notes"}};for(String[] l:ls)locations.add(new Location(l[0],l[1]));journal("Case opened at 11:47 PM.");journal("Victim: Nitheesh Reedy.");journal("Primary crime scene: basement parking.");journal("Objective: establish motive, opportunity, method and proof.");}void addEvidence(String e){if(evidence.add(e))journal("New evidence: "+e);if(evidence.contains("Research project metadata")&&evidence.contains("Deleted research file"))evidence.add("Final encrypted file");if(evidence.contains("Blood pattern at parking bay")&&evidence.contains("Partial CCTV timestamp"))evidence.add("Phone recovered");}boolean hasEvidence(String e){return evidence.contains(e);}void journal(String s){journal.add("• "+s);}String journalText(){StringBuilder b=new StringBuilder();for(String s:journal)b.append(s).append('\n');return b.toString();}String theory(){return connections.isEmpty()?"You have clues, but no connected theory yet.":"The evidence increasingly suggests that Nitheesh's research, his deleted files, and the basement meeting were part of one planned confrontation. Do not let the obvious revenge motive distract you from the digital evidence.";}String[] suspectNames(){return suspects.keySet().toArray(new String[0]);}}
    public static void main(String[] args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}new Main().setVisible(true);});}
}
